layers.vertex:
attribute vec3 aO; attribute float aT, aK; uniform float uTime; varying vec2 vP; varying float vU, vK;
    void main(){ float u = (uTime - aT)/1.250; if (u < 0. || u > 1.750){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vU = u; vK = aK;
      if (aK < .5){ float S = 5.000; vP = position.xy*S; gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(vP.x, .03, -vP.y), 1.); return; }
      vec4 mv = viewMatrix*vec4(aO + vec3(0., 1.3, 0.), 1.);                         /* the eclipse emblem, small billboard over the centre */
      float k = clamp(u/0.600, 0., 1.), S = .9*(1. - pow(1. - k, 3.))*(1. + .15*step(1.000, u)*exp(-(u - 1.000)*8.));   /* slow pop-in, together with the circle; holds until the flash */
      mv.xy += position.xy*S; vP = position.xy; gl_Position = projectionMatrix*mv; }

layers.fragment:
uniform float uTime; uniform vec3 uS, uSL, uM, uML; varying vec2 vP; varying float vU, vK; float eox(float x){ return x >= 1. ? 1. : 1. - pow(2., -10.*x); }
    float line(float d, float w){ return exp(-d*d/(w*w)); }
    float h(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7)))*43758.5); }
    float vn(vec2 p){ vec2 i = floor(p), f = fract(p); f = f*f*(3. - 2.*f);
      return mix(mix(h(i), h(i + vec2(1., 0.)), f.x), mix(h(i + vec2(0., 1.)), h(i + vec2(1., 1.)), f.x), f.y); }
    void main(){ vec3 c = vec3(0.); float al = 0.;
      if (vK < .5){
        float r = length(vP), a = atan(vP.y, vP.x), R = 4.500, u = vU;
        float side = smoothstep(-.06, .06, vP.x);                                    /* 0 = Sun half (left), 1 = Moon half (right) */
        vec3 col = mix(uS, uM, side), lig = mix(uSL, uML, side);
        float ero = vn(vP*2.2);                                                        /* alpha erosion after the hit */
        float fin = 1. - smoothstep(1.050, 1.650, u + .45*ero - .1);
        /* the circle: drawn from the far point to the near point on both halves at once */
        float sweep = eox(clamp(u/0.350, 0., 1.))*3.2, ang = acos(clamp(vP.y/max(r, 1e-3), -1., 1.));
        float drawn = smoothstep(sweep, sweep - .25, ang);
        float border = (line(r - R, .03) + line(r - R, .16)*.07 + line(r - R*.86, .012)*.18)*drawn;
        /* two opposite half rings converge from the border to the centre, accelerating, turning in opposite directions */
        float t = clamp((u - 0.300)/0.700, 0., 1.), e = t*t, Rc = mix(R*.97, .12, e);
        float live = step(0.300, u)*step(u, 1.000);
        float aS = a + e*1.4, aM = a - e*1.4;
        float inS = smoothstep(.1, -.1, cos(aS)), inM = smoothstep(-.1, .1, cos(aM));
        float ray = pow(.5 + .5*cos(aS*18.), 10.)*step(0., r - Rc)*smoothstep(Rc + .45*(1. - .6*e), Rc, r);   /* sun: short star rays */
        float sunR = (line(r - Rc, .035) + ray*.8)*inS;
        float moonW = .03 + .07*max(cos(aM), 0.);                                     /* moon: crescent thickness */
        float moonR = smoothstep(moonW, 0., abs(r - Rc - moonW*.5))*inM*.9 + line(r - Rc, .012)*inM;
        vec3 rc = (uS*sunR*1.3 + uSL*line(r - Rc, .01)*inS*.6 + uM*moonR*1.3 + uML*line(r - Rc - moonW*.5, .008)*inM*.5)*live*(1. + e*1.5);
        /* hit frame: clear central flash + a single pulse half gold / half violet out to the border */
        float k = clamp((u - 1.000)/.4, 0., 1.), after = step(1.000, u);
        float flash = exp(-r*r/.5)*exp(-max(u - 1.000, 0.)*9.)*after*1.2;
        float Rp = .2 + (R - .2)*eox(k);
        float pulse = (line(r - Rp, .07 + .1*(1. - k)) + line(r - Rp, .3)*.10)*(1. - k)*after*smoothstep(R + .2, R - .2, r);
        c = col*(border*1.1 + pulse*.95)*fin + lig*(border*.25 + pulse*.28)*fin + rc + mix(vec3(1.), .5*(uSL + uML), .5)*flash;
        c *= smoothstep(R + .5, R + .3, r);
      } else {
        /* the eclipse emblem: black disc, gold corona of rays on the left, violet crescent rim on the right (the icon) */
        vec2 q = vP; float r = length(q), a = atan(q.y, q.x), u = vU - 1.000;
        float left = smoothstep(.05, -.05, q.x);
        float core = smoothstep(.43, .40, r);
        float cor = pow(.5 + .5*cos(a*14. + sin(r*18.)*.8), 3.)*smoothstep(.42, .5, r)*smoothstep(.85, .5, r)*left;   /* wavy sun rays */
        float rimS = line(r - .43, .02)*left*1.05 + line(r - .43, .1)*left*.12;
        /* Moon: a true crescent (Moon Stance style) - line outline + faint fill; thickest on the right, tips meeting the sun at the top and bottom */
        float dO = r - .43, dI = length(q + vec2(.12, 0.)) - .4466;
        float cres = smoothstep(.006, -.006, dO)*smoothstep(-.006, .006, dI);
        float cEdge = line(dO, .012)*smoothstep(-.01, .01, dI) + line(dI, .012)*smoothstep(.01, -.01, dO);
        float ero = vn(q*7.), fin = 1. - smoothstep(.35, .7, u + .3*ero);
        c = (uS*(cor*1.2 + rimS) + uSL*rimS*.4 + uM*(cres*.22 + cEdge*1.05) + uML*cEdge*.35)*fin;
        al = core*.92*fin; c *= 1. - core*(1. - cres)*.95;
        c += (uSL + uML)*.5*exp(-r*r*30.)*step(0., u)*exp(-u*14.)*2.;                            /* short clear pop */
        c *= smoothstep(1., .9, r); al *= smoothstep(1., .9, r);
      }
      if (!(max(c.r, max(c.g, max(c.b, al))) >= .002)) discard; gl_FragColor = vec4(c, al); }
